-- Primeiro como rascunho, depois no status final: o histórico ganha as duas
-- gravações (contrato_versoes), como no uso real.
insert into comercial.contratos (
  tipo, status, etapa_atual, lucs, bloco, area_m2, locatario_nome, parte_tipo,
  garantia, aluguel, inicio, termino, dados, exemplo
)
select 'contrato', 'rascunho', least(e.etapa, 3), e.lucs, e.bloco, e.area,
  e.locatario, e.parte, e.garantia, e.aluguel, e.inicio, e.termino, e.dados, true
from exemplo_contratos e
order by e.n;

update comercial.contratos c
set status = case when e.status = 'gerado' then 'pronto' else e.status end,
    etapa_atual = e.etapa
from exemplo_contratos e
where c.exemplo and c.tipo = 'contrato' and c.lucs = e.lucs and e.status <> 'rascunho';

update comercial.contratos c
set status = 'gerado'
from exemplo_contratos e
where c.exemplo and c.tipo = 'contrato' and c.lucs = e.lucs and e.status = 'gerado';

insert into comercial.contratos (
  tipo, status, etapa_atual, lucs, bloco, locatario_nome, parte_tipo, inicio,
  termino, contrato_enet_id, dados, exemplo
)
select 'distrato', 'rascunho', 1, array[d.luc], d.bloco, d.locatario, d.parte,
  d.inicio, d.termino, d.contrato_enet, d.dados, true
from exemplo_distratos d;

-- Kit entregue com os prontos e gerados: a versão atual de cada documento.
insert into comercial.contrato_kit (contrato_id, versao_id)
select c.id, v.id
from comercial.contratos c
join comercial.kit_versoes v on v.atual
join comercial.kit_documentos k on k.id = v.documento_id and k.ativo
where c.exemplo and c.tipo = 'contrato' and c.status <> 'rascunho'
  and (k.todo_contrato or c.bloco = any (k.blocos))
on conflict do nothing;

-- Datas espalhadas (o gatilho põe now() em toda gravação).
alter table comercial.contratos disable trigger antes_de_gravar;
alter table comercial.contratos disable trigger registrar_versao;

update comercial.contratos c
set atualizado_em = now() - make_interval(days => least(e.dias, coalesce(e.gerado, e.dias)), mins => e.n),
    criado_em = now() - make_interval(days => e.dias + 7, mins => e.n),
    gerado_em = case when e.gerado is null then null
      else now() - make_interval(days => e.gerado, mins => e.n + 1) end
from exemplo_contratos e
where c.exemplo and c.tipo = 'contrato' and c.lucs = e.lucs;

update comercial.contratos c
set atualizado_em = now() - make_interval(days => d.dias),
    criado_em = now() - make_interval(days => d.dias + 2)
from exemplo_distratos d
where c.exemplo and c.tipo = 'distrato' and c.contrato_enet_id = d.contrato_enet;

alter table comercial.contratos enable trigger antes_de_gravar;
alter table comercial.contratos enable trigger registrar_versao;

-- O histórico acompanha: a primeira gravação na criação, a última na atualização.
update comercial.contrato_versoes v
set em = case when v.id = (
    select min(x.id) from comercial.contrato_versoes x where x.contrato_id = v.contrato_id
  ) then c.criado_em else c.atualizado_em end
from comercial.contratos c
where c.id = v.contrato_id and c.exemplo;

drop table exemplo_contratos;
drop table exemplo_distratos;
